  [[nodiscard]] const SemanticLoanInfo *findLoan(SemanticLoanId id) const {
    if (id == 0 || id > retainedLoans.size()) {
      return nullptr;
    }
    const SemanticLoanInfo &loan = retainedLoans[id - 1];
    return loan.id == id ? &loan : nullptr;
  }

